#define PI 3.1415
#define PI_2 6.28318
#define MIN_DISTANCE 0.009
#define MAX_DISTANCE 30. 
#define MAX_SHADOW_DISTANCE 10. 

#define PRECISION 0.1
#define MAX_STEPS 55
#define MAX_STEPS_SHADOW 25
#define BALL_RADIUS 3.4
#define SMALL_BALL_RADIUS (BALL_RADIUS / 6.)
#define REPEAT_BAUBLE_Y 2.
#define DEG_TO_RAD 0.0174532925

struct Material {
    vec3 ambientColor;
    vec3 diffuseColor;
    vec3 specularColor;
    float alpha;
};


Material gold() {
  vec3 aCol = 0.4 * vec3(0.7, 0.5, 0);
  vec3 dCol = 0.7 * vec3(0.9, 0.9, 0);
  vec3 sCol = 0. * vec3(1, 1, 1);
  float a = 25.;

  return Material(aCol, dCol, sCol, a);
}


Material silver() {
  vec3 ambientColor = 0.5 * vec3(0.8);
  vec3 diffuseColor = 0.3 * vec3(0.3);
  vec3 specularColor = .9 * vec3(1, 1, 1);
  float alpha = 10.;

  return Material(ambientColor, diffuseColor, specularColor, alpha);
}


struct Surface {
    Material m; // material
    float d; // distance
};


Surface sdWavedSphere(vec3 p, vec3 c, float r, float waveFactor, Material m) {
    return Surface(m, length(p-c) - r-1.0+0.02*sin(waveFactor*(p.y)));
}


Surface sdSphere(vec3 pr, vec3 c, float r, Material m) {
    return Surface(m, length(pr-c) - r);
}


//https://iquilezles.org/articles/distfunctions/
Surface sdRoundedCylinder( vec3 p, float ra, float rb, float h, Material m )
{
  vec2 d = vec2( length(p.xz)-2.0*ra+rb, abs(p.y) - h );
  return Surface(m, min(max(d.x,d.y),0.0) + length(max(d,0.0)) - rb);
}



Surface minSurface(Surface s1, Surface s2) {
    Surface res = s1;
    if (res.d > s2.d) res = s2;
    return res;
}

Surface roundMergeWithMaterial (Surface surface1, Surface surface2, float radius) {
    float item1 = surface1.d;
    float item2 = surface2.d;
    float touchDistance = abs(item1 - item2);


    vec2 intersection = vec2(item1 - radius, item2 - radius);
    intersection = min(intersection, 0.0);
    float insideDistance = length(intersection);
    float simpleUnion = min(item1, item2);
    float outsideDistance = max(simpleUnion, radius);
    Surface res; res.d = outsideDistance - insideDistance;


    if (touchDistance >= radius) {
        if (item1 <= item2) res.m = surface1.m; else res.m = surface2.m;
    } else {
        float rr = touchDistance / radius;
        if (surface1.d < surface2.d) {
            res.m = Material(mix(surface2.m.ambientColor, surface1.m.ambientColor, rr), 
                             mix(surface2.m.diffuseColor, surface1.m.diffuseColor, rr), 
                             mix(surface2.m.specularColor, surface1.m.specularColor, rr), 
                             mix(surface2.m.alpha, surface1.m.alpha, rr));

    } else {
            res.m = surface2.m;
        }
    }


    return  res;
}

Surface roundMerge(Surface surface1, Surface surface2, float radius) {
    float item1 = surface1.d;
    float item2 = surface2.d;

    vec2 intersection = vec2(item1 - radius, item2 - radius);
    intersection = min(intersection, 0.0);
    float insideDistance = -length(intersection);
    float simpleUnion = min(item1, item2);
    float outsideDistance = max(simpleUnion, radius);
    Surface res; res.d = insideDistance + outsideDistance;
    res.m = surface1.m;
    return  res;
}

// based on  https://iquilezles.org/articles/distfunctions/

Surface sdTorus(vec3 p, vec2 t, Material m) {
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return Surface(m, length(q)-t.y);
}


// https://www.shadertoy.com/view/wlycRR
vec2 opModPolar(vec2 p, float n)
{
	float angle = PI / n,
		  a = mod(atan(p.y, p.x), 2. * angle) - angle;
	return length(p) * vec2(cos(a), sin(a));
}


Surface scene(vec3 pr) {
    float sTime = iTime * 0.5;
    vec3 p = pr * rotateY(sTime) * rotateX(320. * DEG_TO_RAD);
    Surface sphere1 = sdWavedSphere(p * rotateZ(0. * DEG_TO_RAD), vec3(0., 0., 0.0), BALL_RADIUS * 0.7, 8., gold()); 
    Surface cylinder1 = sdRoundedCylinder(p-vec3(.0, BALL_RADIUS + 0.17 * BALL_RADIUS * 0.2, 0.0), 0.1, 0.03, BALL_RADIUS * 0.05, gold());
    Surface cylinder2 = sdRoundedCylinder(p-vec3(.0, BALL_RADIUS + 0.5 * BALL_RADIUS * 0.2, 0.0), 0.1, 0.03, BALL_RADIUS * 0.02, silver());
    Surface u1 = sdTorus(rotateX(90. * DEG_TO_RAD) * (p-vec3(0.0, BALL_RADIUS * 1.24 , 0.0)), vec2(0.3, 0.04), silver());
    Surface res = roundMergeWithMaterial(u1, minSurface(cylinder1, cylinder2), 0.1);
    res = minSurface(res, sphere1);

    vec3 pr1 = pr * rotateY(PI - sTime / 1.);
    vec3 pp; pp.xz = opModPolar((pr1.xz), 15.);
    pp.y = mod(pr1.y, REPEAT_BAUBLE_Y) - REPEAT_BAUBLE_Y / 2.;

    int cycle = 1;
    cycle = int(round((pr1.y - (pp.y - REPEAT_BAUBLE_Y / 2.)) / REPEAT_BAUBLE_Y));

    if (abs(cycle) < 6){
        pp.x -= 10.5 - sin(iTime + float(cycle) * 0.15) * 7.;
        Surface sphere2 = sdSphere(pp, vec3(0., 0., 0.0), SMALL_BALL_RADIUS, silver()); 
        Surface cylinder3 = sdRoundedCylinder(pp-vec3(.0, SMALL_BALL_RADIUS + 0.17 * SMALL_BALL_RADIUS * 0.4, 0.0), 0.07, 0.03, SMALL_BALL_RADIUS * 0.05, silver());
        Surface cylinder4 = sdRoundedCylinder(pp-vec3(.0, SMALL_BALL_RADIUS + 0.5 * SMALL_BALL_RADIUS * 0.4, 0.0), 0.07, 0.03, SMALL_BALL_RADIUS * 0.02, gold());
        //Surface cylinder5 = sdRoundedCylinder(pp-vec3(.0, SMALL_BALL_RADIUS + 4.5 * SMALL_BALL_RADIUS * 0.4, 0.0), 0.01, 0.03, 0.2, gold());
        Surface u2 = sdTorus(rotateX(90. * DEG_TO_RAD) * (pp-vec3(0.0, SMALL_BALL_RADIUS * 1.5 , 0.0)), vec2(0.1, 0.02), gold());
        Surface res2 = roundMergeWithMaterial(u2, minSurface(cylinder3, cylinder4), 0.1);
        //res2 = roundMergeWithMaterial(res2, cylinder5, 0.1);
        res2 = roundMergeWithMaterial(res2, sphere2, 0.05);

        res = minSurface(res, res2);
    }

    return res;
}




// vector normal to sphere with cener c and radius r
vec3 calcNormal(vec3 p) {
  vec2 e = vec2(0.0015, -0.0015);
  return normalize(
    e.xyy * scene(p + e.xyy).d +
    e.yyx * scene(p + e.yyx).d +
    e.yxy * scene(p + e.yxy).d +
    e.xxx * scene(p + e.xxx).d);
}


